rng=np.random.default_rng(2)
def run(f,n,tries=120):
    bb=None
    for it in range(tries):
        p0=rng.normal(size=n)
        try:
            r=least_squares(lambda p: f(p)-sigma, p0, max_nfev=1500)
            if np.all(np.isfinite(r.fun)) and (bb is None or r.cost<bb.cost): bb=r
        except Exception: pass
    return np.mean((f(bb.x)-sigma)**2)/np.var(sigma), np.round(bb.x,4)
