from scipy.optimize import least_squares
rng=np.random.default_rng(4)
def S(p,Cf,nC):
    A=p[0]/T; q=p[1]+p[2]/T+p[3]/T**2
    return A*eps*np.exp(-q*eps)+Cf(p[4:4+nC])
Cs={
 'poly+1/T':(lambda c: c[0]+c[1]*T+c[2]*T**2+c[3]/T,4),
 'exp':(lambda c: c[0]+c[1]*np.exp(-c[2]*T),3),
 'log':(lambda c: c[0]+c[1]*np.log(T)+c[2]/T,3),
 'invpoly3':(lambda c: c[0]+c[1]/T+c[2]/T**2+c[3]/T**3,4),
 'poly4':(lambda c: c[0]+c[1]*T+c[2]*T**2+c[3]*T**3,4),
 'gauss':(lambda c: c[0]+c[1]*np.exp(-c[2]*(T-c[3])**2),4),
}
for k,(Cf,nC) in Cs.items():
    bb=None
    for it in range(60):
        p0=rng.normal(size=4+nC)
        try:
            r=least_squares(lambda p: S(p,Cf,nC)-sigma, p0, max_nfev=1000)
            if np.all(np.isfinite(r.fun)) and (bb is None or r.cost<bb.cost): bb=r
        except Exception: pass
    print(k, np.mean((S(bb.x,Cf,nC)-sigma)**2)/np.var(sigma), np.round(bb.x,3))
